    "let cfgProvider='',cfgModel='',cfgApiKey=false;\n"
    "let msgCount=0,hasSent=false,typingEl=null,typewriterActive=false;\n"
    "let atBottom=true;\n"
    "\n"
    "function updateModelHint(){\n"
    "  const el=$('model-hint');\n"
    "  if(el)el.textContent=cfgModel||'';\n"
    "}\n"
    "\n"
    "const $=id=>document.getElementById(id);\n"
    "const msgInput=$('msg-input'),sendBtn=$('send-btn'),msgArea=$('messages');\n"
    "const statusDot=$('status-dot');\n"
    "const mainEl=$('main');\n"
    "const chatArea=$('chat-area'),scrollBtn=$('scroll-btn');\n"
    "\n"
    "// ============================== Scroll ==============================\n"
    "function scrollBottom(){\n"
    "  chatArea.scrollTop=chatArea.scrollHeight;checkScroll();\n"
    "}\n"
    "function isAtBottom(){\n"
    "  return chatArea.scrollHeight-chatArea.scrollTop-chatArea.clientHeight<60;\n"
    "}\n"
    "function checkScroll(){\n"
    "  atBottom=isAtBottom();\n"
    "  scrollBtn.classList.toggle('show',!atBottom&&msgCount>0);\n"
    "}\n"
    "chatArea.addEventListener('scroll',checkScroll);\n"
    "\n"
    "function pad(n){return('0'+n).slice(-2)}\n"
    "function timeStr(){const d=new Date();return pad(d.getHours())+':'+pad(d.getMinutes());}\n"
    "\n"
    "// ============================== Connection ==============================\n"
    "function setStatus(state){\n"
    "  statusDot.className='dot '+state;\n"
    "  const label=$('status-label');\n"
    "  if(label){label.className='status-label '+state;label.textContent=state==='green'?'已连接':state==='yellow'?'连接中':'已断开';}\n"
    "}\n"
    "\n"
    "function connect(){\n"
    "  if(ws){ws.onclose=null;ws.close();ws=null;}\n"
    "  if(reconnTimer){clearTimeout(reconnTimer);reconnTimer=null;}\n"
    "  const host=window.location.hostname;\n"
    "  const url='ws://'+host+':18789';\n"
    "  setStatus('yellow');\n"
    "  ws=new WebSocket(url);\n"
    "  // Timeout: device may need up to 30s to boot after RST\n"
    "  let connTimeout=setTimeout(function(){\n"
    "    if(ws&&ws.readyState!==1){\n"
    "      ws.onclose=function(){};\n"
    "      ws.close();ws=null;\n"
    "      setStatus('red');\n"
    "      scheduleReconnect();\n"
    "    }\n"
    "  },30000);\n"
    "\n"
    "  ws.onopen=function(){\n"
    "    clearTimeout(connTimeout);\n"
    "    connected=true;reconnCount=0;\n"
    "    setStatus('green');\n"
    "    while(pendingMsgs.length){\n"
    "      const m=pendingMsgs.shift();\n"
    "      try{ws.send(m);}catch(e){pendingMsgs.unshift(m);break;}\n"
    "    }\n"
    "    if(sendPing)clearInterval(sendPing);\n"
    "    sendPing=setInterval(function(){\n"
    "      try{\n"
    "        if(ws.readyState!==1){clearInterval(sendPing);return;}\n"
    "        ws.send('__ping__');\n"
    "        if(pongTimer)clearTimeout(pongTimer);\n"
    "        pongTimer=setTimeout(function(){if(ws)ws.close();},8000);\n"
    "      }catch(e){clearInterval(sendPing);}\n"
    "    },10000);\n"
    "  };\n"
    "\n"
    "  ws.onmessage=function(e){\n"
    "    if(typeof e.data!=='string'||!e.data.trim())return;\n"
    "    const t=e.data.trim();\n"
    "    if(t==='__pong__'){if(pongTimer){clearTimeout(pongTimer);pongTimer=null;}return;}\n"
    "    if(t==='__ping__')return;\n"
    "    hideTyping();\n"
    "    if(typewriterActive)finishTypewriter();\n"
    "    addMsg('ai',t);\n"
    "  };\n"
    "\n"
    "  ws.onclose=function(){\n"
    "    clearTimeout(connTimeout);\n"
    "    connected=false;\n"
    "    hideTyping();if(typewriterActive)finishTypewriter();\n"
    "    if(sendPing){clearInterval(sendPing);sendPing=null;}\n"
    "    if(pongTimer){clearTimeout(pongTimer);pongTimer=null;}\n"
    "    ws=null;\n"
    "    scheduleReconnect();\n"
    "  };\n"
    "\n"
    "  ws.onerror=function(){\n"
    "    clearTimeout(connTimeout);\n"
    "    setStatus('red');\n"
    "    if(ws){ws.onclose=null;ws.close();ws=null;}\n"
    "    scheduleReconnect();\n"
    "  };\n"
    "}\n"
    "\n"
    "function scheduleReconnect(){\n"
    "  if(reconnTimer)return; // don't stack\n"
    "  reconnCount++;\n"
    "  // Backoff: 1s, 2s, 4s, 8s, 16s, 30s, 30s... (infinite retries)\n"
    "  const delay=Math.min(1000*Math.pow(2,Math.min(reconnCount-1,5)),30000);\n"
    "  setStatus('yellow');\n"
    "  reconnTimer=setTimeout(connect,delay);\n"
    "}\n"
    "\n"
    "// ============================== Messages ==============================\n"
    "let pendingMsgs=[];\n"
    "\n"
    "function addMsg(type,text){\n"
    "  if(type==='ai'){startTypewriter(text);return;}\n"
    "  if(!hasSent){hasSent=true;mainEl.classList.add('chatting');}\n"
    "  const row=document.createElement('div');\n"
    "  row.className='msg '+type;\n"
    "  const bub=document.createElement('div');\n"
    "  bub.className='bubble';\n"
    "  bub.innerHTML=(type==='user'?escapeHtml(text):renderMarkdown(text));\n"
    "  const t=document.createElement('span');\n"
    "  t.className='time';t.textContent=timeStr();\n"
    "  bub.appendChild(t);row.appendChild(bub);\n"
    "  msgArea.appendChild(row);\n"
    "  msgCount++;\n"
    "  if(atBottom)scrollBottom();\n"
    "  if(type!=='system')saveMsg(type,text);\n"
    "}\n"
    "\n"
    "function addSystem(text){\n"
    "  const row=document.createElement('div');\n"
    "  row.className='msg system';\n"
    "  const bub=document.createElement('div');\n"
    "  bub.className='bubble';bub.textContent=text;\n"
    "  row.appendChild(bub);\n"
    "  msgArea.appendChild(row);\n"
    "  if(atBottom)scrollBottom();\n"
    "  saveMsg('system',text);\n"
    "}\n"
    "\n"
    "// ============================== Typing ==============================\n"
    "function showTyping(){\n"
    "  if(typingEl)return;\n"
    "  typingEl=document.createElement('div');\n"
    "  typingEl.className='msg ai';\n"
    "  typingEl.innerHTML='<div class=\"typing\"><span></span><span></span><span></span></div>';\n"
    "  msgArea.appendChild(typingEl);if(atBottom)scrollBottom();\n"
    "}\n"
    "function hideTyping(){\n"
    "  if(typingEl){typingEl.remove();typingEl=null;}\n"
    "}\n"
    "\n"
    "// ============================== Typewriter ==============================\n"
    "let typewriterTimer=null,typewriterRow=null,typewriterBub=null;\n"
    "let typewriterIdx=0,typewriterRaw='';\n"
    "\n"
    "function startTypewriter(text){\n"
    "  if(!text)return;\n"
    "  stopTypewriter();\n"
    "  if(!hasSent){hasSent=true;mainEl.classList.add('chatting');}\n"
    "  typewriterActive=true;typewriterRaw=text;\n"
    "  const escaped=escapeHtml(text);\n"
    "  hideTyping();\n"
    "  typewriterRow=document.createElement('div');\n"
    "  typewriterRow.className='msg ai';\n"
    "  typewriterBub=document.createElement('div');\n"
    "  typewriterBub.className='bubble';\n"
    "  typewriterBub.innerHTML='<span class=\"md\"></span><span class=\"cursor\"></span>';\n"
    "  const t=document.createElement('span');t.className='time';t.textContent=timeStr();\n"
    "  typewriterBub.appendChild(t);\n"
    "  typewriterRow.appendChild(typewriterBub);\n"
    "  msgArea.appendChild(typewriterRow);msgCount++;\n"
    "  if(atBottom)scrollBottom();\n"
    "  setTimeout(()=>t.style.opacity='1',800);\n"
    "  typewriterIdx=0;\n"
    "  const speed=text.length>200?8:16;\n"
    "  typewriterTimer=setInterval(function(){\n"
    "    if(typewriterIdx>=escaped.length){finishTypewriter();return;}\n"
    "    typewriterIdx=Math.min(typewriterIdx+3,escaped.length);\n"
    "    typewriterBub.querySelector('.md').textContent=escaped.substring(0,typewriterIdx);\n"
    "    if(atBottom)scrollBottom();\n"
    "  },speed);\n"
    "}\n"
    "function finishTypewriter(){\n"
    "  if(!typewriterActive)return;\n"
    "  typewriterActive=false;\n"
    "  if(typewriterTimer){clearInterval(typewriterTimer);typewriterTimer=null;}\n"
    "  const md=typewriterBub.querySelector('.md');\n"
    "  const cur=typewriterBub.querySelector('.cursor');\n"
    "  if(md)md.innerHTML=renderMarkdown(typewriterRaw);\n"
    "  if(cur)cur.remove();\n"
    "  saveMsg('ai',typewriterRaw);\n"
    "  typewriterRow=null;typewriterBub=null;typewriterRaw='';\n"
    "}\n"
    "function stopTypewriter(){\n"
    "  if(typewriterTimer){clearInterval(typewriterTimer);typewriterTimer=null;}\n"
    "  typewriterActive=false;\n"
    "  if(typewriterBub){const c=typewriterBub.querySelector('.cursor');if(c)c.remove();}\n"
    "  typewriterRow=null;typewriterBub=null;typewriterRaw='';\n"
    "}\n"
    "\n"
    "// ============================== Markdown ==============================\n"
    "function renderMarkdown(t){\n"
    "  t=t.replace(/```(\\w*)\\n?([\\s\\S]*?)```/g,function(_,l,c){return '<pre><code>'+escapeHtml(c.trim())+'</code></pre>';});\n"
    "  t=t.replace(/`([^`]+)`/g,'<code>$1</code>');\n"
    "  t=t.replace(/\\*\\*(.+?)\\*\\*/g,'<strong>$1</strong>');\n"
    "  t=t.replace(/__(.+?)__/g,'<strong>$1</strong>');\n"
    "  t=t.replace(/\\*(.+?)\\*/g,'<em>$1</em>');\n"
    "  t=t.replace(/_(.+?)_/g,'<em>$1</em>');\n"
    "  t=t.replace(/\\[([^\\]]+)\\]\\(([^)]+)\\)/g,'<a href=\"$2\" target=\"_blank\" rel=\"noopener\">$1</a>');\n"
    "  t=t.replace(/^[\\s]*[-*]\\s+(.+)$/gm,'<li>$1</li>');\n"
    "  t=t.replace(/((?:<li>.*<\\/li>\\n?)+)/g,'<ul>$1</ul>');\n"
    "  t=t.replace(/^[\\s]*\\d+\\.\\s+(.+)$/gm,'<li>$1</li>');\n"
    "  t=t.replace(/((?:<li>.*<\\/li>\\n?)+)(?!\\s*<\\/(?:ul|ol)>)/g,function(m){return m.includes('<ul>')||m.includes('<ol>')?m:'<ol>'+m+'</ol>';});\n"
    "  t=t.replace(/\\n/g,'<br>');\n"
    "  return t;\n"
    "}\n"
    "function escapeHtml(str){\n"
    "  const m={'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'};\n"
    "  return str.replace(/[&<>\"']/g,c=>m[c]);\n"
    "}\n"
    "\n"
    "// ============================== Quick Send ==============================\n"
    "function quickSend(text){\n"
    "  msgInput.value=text;sendMessage();\n"
    "}\n"
    "\n"
    "// ============================== Send ==============================\n"
    "function sendMessage(){\n"
    "  const text=msgInput.value.trim();\n"
    "  if(!text)return;\n"
    "  msgInput.value='';msgInput.style.height='auto';\n"
    "  if(text.startsWith('/')){\n"
    "    const sp=text.indexOf(' ');const cmd=sp>0?text.substring(1,sp).toLowerCase():text.substring(1).toLowerCase();\n"
    "    const arg=sp>0?text.substring(sp+1).trim():'';\n"
    "    if(execCmd(cmd,arg))return;\n"
    "  }\n"
    "  addMsg('user',text);\n"
    "  showTyping();\n"
    "  if(!connected||!ws){pendingMsgs.push(text);addSystem('消息已暂存');return;}\n"
    "  try{ws.send(text);}catch(e){pendingMsgs.push(text);addSystem('发送失败');}\n"
    "}\n"
    "\n"
    "function execCmd(cmd,arg){\n"
    "  switch(cmd){\n"
    "    case 'help':addMsg('ai','可用指令: /key /model /provider /wifi /status /clear /ping');return true;\n"
    "    case 'clear':clearChat();return true;\n"
    "    case 'model':if(arg){sendRaw('llm_model '+arg);cfgModel=arg;updateModelHint();saveConfig();addSystem('✓ 模型: '+arg);}else addSystem('用法: /model <模型名>');return true;\n"
    "    case 'provider':if(arg){sendRaw('llm_provider '+arg);cfgProvider=arg;saveConfig();addSystem('✓ 提供商: '+arg);}else addSystem('用法: /provider <名称>');return true;\n"
    "    case 'key':if(arg){sendRaw('llm_key '+arg);cfgApiKey=true;saveConfig();addSystem('✓ API Key 已设置');}else addSystem('用法: /key <API Key>');return true;\n"
    "    case 'wifi':sendRaw('wifi_status');return true;\n"
    "    case 'status':sendRaw('status');return true;\n"
    "    case 'ping':addSystem('pong');return true;\n"
    "    default:addSystem('未知指令 /'+cmd+'  /help 查看帮助');return true;\n"
    "  }\n"
    "}\n"
    "function sendRaw(text){\n"
    "  if(!connected||!ws){pendingMsgs.push(text);return;}\n"
    "  try{ws.send(text);}catch(e){pendingMsgs.push(text);}\n"
    "}\n"
    "\n"
    "// ============================== Config ==============================\n"
    "const CFG_KEY='mimi_web_config';\n"
    "function saveConfig(){\n"
    "  try{localStorage.setItem(CFG_KEY,JSON.stringify({provider:cfgProvider,model:cfgModel,apikey:cfgApiKey}));}catch(e){}\n"
    "}\n"
    "function loadConfig(){\n"
    "  try{\n"
    "    const d=JSON.parse(localStorage.getItem(CFG_KEY));\n"
    "    if(d){\n"
    "      if(d.provider)cfgProvider=d.provider;\n"
    "      if(d.model){cfgModel=d.model;updateModelHint();}\n"
    "      if(d.apikey)cfgApiKey=true;\n"
    "    }\n"
    "  }catch(e){}\n"
    "}\n"
    "\n"
    "const STORAGE_KEY='mimi_chat_msgs';\n"
    "function saveMsg(type,content){\n"
    "  try{\n"
    "    let msgs=JSON.parse(localStorage.getItem(STORAGE_KEY))||[];\n"
    "    msgs.push({type,content,time:timeStr()});\n"
    "    if(msgs.length>200)msgs=msgs.slice(-200);\n"
    "    localStorage.setItem(STORAGE_KEY,JSON.stringify(msgs));\n"
    "  }catch(e){}\n"
    "}\n"
    "function loadMessages(){\n"
    "  try{\n"
    "    const msgs=JSON.parse(localStorage.getItem(STORAGE_KEY));\n"
    "    if(!msgs||!msgs.length)return;\n"
    "    for(const m of msgs){\n"
    "      if(m.type==='system'){\n"
    "        const row=document.createElement('div');row.className='msg system';\n"
    "        const b=document.createElement('div');b.className='bubble';b.textContent=m.content||'';\n"
    "        row.appendChild(b);msgArea.appendChild(row);\n"
    "      }else{\n"
    "        const row=document.createElement('div');row.className='msg '+m.type;\n"
    "        const b=document.createElement('div');b.className='bubble';\n"
    "        b.innerHTML=(m.type==='user'?escapeHtml(m.content||''):renderMarkdown(m.content||''));\n"
    "        const t=document.createElement('span');t.className='time';t.textContent=m.time||'';\n"
    "        t.style.opacity='1';b.appendChild(t);row.appendChild(b);\n"
    "        msgArea.appendChild(row);\n"
    "      }\n"
    "      msgCount++;\n"
    "    }\n"
    "    if(msgs.length){hasSent=true;mainEl.classList.add('chatting');scrollBottom();}\n"
    "  }catch(e){}\n"
    "}\n"
    "\n"
    "// ============================== New Chat ==============================\n"
    "function newChat(){\n"
    "  msgArea.innerHTML='';msgCount=0;hasSent=false;\n"
    "  mainEl.classList.remove('chatting');\n"
    "  hideTyping();if(typewriterActive)stopTypewriter();\n"
    "  try{localStorage.removeItem(STORAGE_KEY);}catch(e){}\n"
    "}\n"
    "\n"
    "function clearChat(){newChat();}\n"
    "\n"
    "// ============================== Input ==============================\n"
    "msgInput.addEventListener('input',function(){\n"
    "  this.style.height='auto';\n"
    "  this.style.height=Math.min(this.scrollHeight,200)+'px';\n"
    "});\n"
    "msgInput.addEventListener('keydown',function(e){\n"
    "  if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage();}\n"
    "});\n"
    "\n"
    "// ============================== Init ==============================\n"
    "loadConfig();\n"
    "loadMessages();\n"
    "// Reset state and start connecting immediately\n"
    "reconnCount=0;\n"
    "if(reconnTimer){clearTimeout(reconnTimer);reconnTimer=null;}\n"
    "if(ws){ws.onclose=null;ws.close();ws=null;}\n"
    "connect();\n"
    "})();\n"
    "</script>\n"
    "</body>\n"
    "</html>\n"
    "\n";

#define WEB_UI_HTML_LEN (sizeof(WEB_UI_HTML) - 1)

#endif /* WEB_UI_H */
